package org.traceform.edge;
import java.io.*; import java.nio.file.*; import org.json.*;
public final class ColdSizeProbe {
 public static void main(String[] args)throws Exception {
  File root=new File(args[0]); if(!root.mkdir())throw new IllegalStateException("fresh synthetic root required");
  JSONObject core=new JSONObject(new String(Files.readAllBytes(new File(args[1]).toPath()),"UTF-8"));
  ModelEngine model=ModelEngine.fromRegistry(core,core.getString("model_version"),core.getString("model_sha256"));
  if(model.names.length!=128 || model.tokens.length!=16)throw new IllegalStateException("full asset shape required");
  File candidates=new File(root,"candidates"),directory=new File(root,"registry");
  try(android.database.sqlite.SQLiteDatabase db=android.database.sqlite.SQLiteDatabase.create(null)) {
   ColdTrajectory.initialize(db); ColdTrajectory.register(db,model.modelVersion,model.normalizerDigest,model.tokens,model.coldBundle()); ColdLineage.migrateOnce(db);
   db.execSQL("CREATE TABLE frames (ts INTEGER PRIMARY KEY,payload TEXT)"); db.execSQL("CREATE TABLE warm_trajectory (bucket INTEGER PRIMARY KEY,ts INTEGER,payload TEXT,n INTEGER)");
   NativeModelRegistry registry=new NativeModelRegistry(directory,model); ModelEngine current=model;
   java.lang.reflect.Method report=NativeRegistryFixture.class.getDeclaredMethod("report",ModelEngine.class,String.class);report.setAccessible(true);
   java.util.Random random=new java.util.Random(48);
   for(int step=1;step<=7;step++) {
    db.execSQL("INSERT INTO warm_trajectory VALUES (?,?,?,1)",new Object[]{step,step*30000L,new JSONObject().put("model_version",current.modelVersion).toString()});
    JSONObject r=(JSONObject)report.invoke(null,current,String.format("%064d",step)); JSONArray centers=r.getJSONArray("candidate_centers"),rows=new JSONArray();
    for(int node=0;node<16;node++){JSONArray row=new JSONArray();for(int dim=0;dim<128;dim++){int index=node*128+dim;double value=centers.getDouble(index)+random.nextGaussian()*0.01;centers.put(index,value);row.put(value);}rows.put(row);}
    r.getJSONObject("potential").put("centers",rows);
    String digest=NativeCandidateStore.save(candidates,current,r);registry.activateWithHistory(candidates,digest,current.modelVersion,db);current=registry.active();
   }
   long total=0; db.beginTransaction();
   try(android.database.Cursor models=db.rawQuery("SELECT namespace FROM cold_models",null)){
    while(models.moveToNext())for(String source:model.tokens)for(String target:model.tokens){long count=1+random.nextInt(1000000000);total=Math.addExact(total,count);db.execSQL("INSERT INTO cold_edges VALUES (?,?,?,?)",new Object[]{models.getString(0),source,target,count});db.execSQL("INSERT OR IGNORE INTO cold_lineage_edges VALUES (?,?,?,0)",new Object[]{model.coldStateNamespace(),source,target});db.execSQL("UPDATE cold_lineage_edges SET n=n+? WHERE namespace=? AND source=? AND target=?",new Object[]{count,model.coldStateNamespace(),source,target});}
    db.setTransactionSuccessful();
   }finally{db.endTransaction();}
   File archive=new File(root,"cold.json.gz");JSONObject result=ColdTrajectory.export(db,archive);
   if(result.getInt("models")!=8 || result.getLong("transitions")!=total || archive.length()>500000)throw new IllegalStateException("full model archive bound failed");
   System.out.println(new JSONObject().put("passed",true).put("export",result).put("dimensions",128).put("tokens",16).put("version_edges",2048).put("lineage_edges",256).put("scope","eight_full_shape_asset_based_synthetic_calibrated_models_dense_edges_not_all_possible_models_or_real_fits"));
  }
 }
}
